import Database from "better-sqlite3";
import { existsSync, mkdirSync } from "node:fs";
import { dirname } from "node:path";

const DB_PATH = "/home/user/qwik-app/wiki.db";

function getDb(): Database.Database {
  // Ensure the directory for the database exists
  const dbDir = dirname(DB_PATH);
  if (!existsSync(dbDir)) {
    mkdirSync(dbDir, { recursive: true });
  }

  const db = new Database(DB_PATH);

  // Enable WAL mode for better concurrent access
  db.pragma("journal_mode = WAL");

  // Create the revisions table if it doesn't exist
  db.exec(`
    CREATE TABLE IF NOT EXISTS revisions (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      slug TEXT NOT NULL,
      user TEXT NOT NULL,
      timestamp INTEGER NOT NULL,
      content_length INTEGER NOT NULL
    )
  `);

  // Create an index on slug + timestamp for faster history queries
  db.exec(`
    CREATE INDEX IF NOT EXISTS idx_revisions_slug_timestamp
    ON revisions(slug, timestamp DESC)
  `);

  return db;
}

export interface Revision {
  id: number;
  slug: string;
  user: string;
  timestamp: number;
  content_length: number;
}

export function insertRevision(
  slug: string,
  user: string,
  content: string,
): Revision {
  const db = getDb();
  const timestamp = Date.now();
  const content_length = content.length;

  const stmt = db.prepare(`
    INSERT INTO revisions (slug, user, timestamp, content_length)
    VALUES (?, ?, ?, ?)
  `);

  const result = stmt.run(slug, user, timestamp, content_length);

  db.close();

  return {
    id: result.lastInsertRowid as number,
    slug,
    user,
    timestamp,
    content_length,
  };
}

export function getRevisions(slug: string): Revision[] {
  const db = getDb();

  const stmt = db.prepare(`
    SELECT id, slug, user, timestamp, content_length
    FROM revisions
    WHERE slug = ?
    ORDER BY timestamp DESC
  `);

  const rows = stmt.all(slug) as Revision[];

  db.close();

  return rows;
}

import { component$ } from "@builder.io/qwik";
import {
  routeLoader$,
  useLocation,
  type DocumentHead,
} from "@builder.io/qwik-city";
import { readFileSync, existsSync } from "node:fs";
import { marked } from "marked";

export const useWikiPage = routeLoader$(({ params, status }) => {
  const slug = params.slug;
  const filePath = `/home/user/qwik-app/wiki-pages/${slug}.md`;

  if (!existsSync(filePath)) {
    status(404);
    return null;
  }

  const raw = readFileSync(filePath, "utf-8");
  const html = marked.parse(raw) as string;

  return { html, slug };
});

export default component$(() => {
  const loc = useLocation();
  const page = useWikiPage();

  if (!page.value) {
    return (
      <div>
        <h1>404 - Page Not Found</h1>
        <p>The wiki page "{loc.params.slug}" does not exist.</p>
      </div>
    );
  }

  return (
    <div class="wiki-content" dangerouslySetInnerHTML={page.value.html} />
  );
});

export const head: DocumentHead = ({ resolveValue }) => {
  const page = resolveValue(useWikiPage);
  return {
    title: page?.slug ? `Wiki - ${page.slug}` : "Wiki - Not Found",
  };
};

import { routeAction$, type RequestHandler } from "@builder.io/qwik-city";
import { writeFileSync, existsSync, mkdirSync } from "node:fs";
import { dirname } from "node:path";
import { insertRevision } from "~/db";

export const onRequest: RequestHandler = ({ request, json }) => {
  // Set CORS/JSON headers for API-like responses
  json(200, { success: true });
};

export const useEditWiki = routeAction$(
  async (data, { params, redirect, request }) => {
    const slug = params.slug;

    let content: string;
    let user: string;

    // Try to parse as JSON first, then fall back to form-urlencoded
    const contentType = request.headers.get("content-type") || "";

    if (contentType.includes("application/json")) {
      const body = await request.json();
      content = body.content;
      user = body.user;
    } else {
      // Form-urlencoded — data is already parsed by Qwik
      content = data.content as string;
      user = data.user as string;
    }

    if (!content || !user) {
      throw new Error("Missing required fields: content and user");
    }

    // Ensure the wiki-pages directory exists
    const dir = `/home/user/qwik-app/wiki-pages`;
    if (!existsSync(dir)) {
      mkdirSync(dir, { recursive: true });
    }

    const filePath = `${dir}/${slug}.md`;

    // Write the markdown file
    writeFileSync(filePath, content, "utf-8");

    // Insert revision log entry
    insertRevision(slug, user, content);

    // Redirect to the wiki page
    throw redirect(302, `/wiki/${slug}`);
  },
);

import { routeLoader$ } from "@builder.io/qwik-city";
import { getRevisions } from "~/db";

export const useRevisions = routeLoader$(({ params }) => {
  const slug = params.slug;
  const revisions = getRevisions(slug);
  return revisions;
});

// This route only returns JSON — no component rendering needed.
// Qwik City will serialize the loader data as JSON when there's no default export
// and the content-type is set appropriately. We use a request handler instead.
import type { RequestHandler } from "@builder.io/qwik-city";

export const onGet: RequestHandler = ({ json, resolveValue }) => {
  const revisions = resolveValue(useRevisions);
  json(200, revisions);
};

